import{a as s}from"./chunk-2RJSKV3I.js";import{a as e}from"./chunk-SH4CHYBR.js";import"./chunk-U37H3HIF.js";var o=s(e,["Facultatif. Seulement pour les mots \xE0 l’\xE9cran, les noms des fichiers que vous cr\xE9ez pour lui et le lien dans la barre lat\xE9rale. Rien n’y est connect\xE9.","Assistants et leurs liens…","Ouvrir \xE0 c\xF4t\xE9 de Grading Studio","Le navigateur l’a emp\xEAch\xE9 de s’ouvrir. Autorisez les fen\xEAtres pop-up pour cette page, puis r\xE9essayez.","Votre assistant","Un lien commence par https://","Son nom","Mon assistant","Aucun, ou non pr\xE9cis\xE9","Aucun assistant indiqu\xE9.","Votre assistant est maintenant {name}.","Ouvrir {name} maintenant","Un clic sur son nom l’ouvre","Un autre…","Les autres que vous utilisez","Un clic sur le nom de votre assistant dans la barre lat\xE9rale les affiche aussi. Choisissez-en un l\xE0 : il s’ouvre et devient celui qui est utilis\xE9, avec son propre lien.","Dans une fen\xEAtre \xE0 droite","C\xF4te \xE0 c\xF4te : il est dans la barre lat\xE9rale sur chaque \xE9cran. Dans Chrome, faites un clic droit dessus et choisissez Ouvrir le lien en vue fractionn\xE9e pour avoir les deux dans une seule fen\xEAtre. Grading Studio ne lui envoie rien ; il ne voit que ce que vous collez ou joignez.","Changer votre assistant","Changer le lien de votre assistant","Changer les assistants que vous utilisez","Changer l’endroit o\xF9 s’ouvre votre assistant","Dans un nouvel onglet","S’ouvre sur","Vide pour sa page habituelle. Un lien \xE0 vous peut mener au compte de votre \xE9tablissement, \xE0 un projet ou \xE0 votre propre assistant enregistr\xE9.","Votre assistant IA","Comment les fichiers que vous rendez sont pr\xE9par\xE9s au d\xE9part. La case Rendre peut changer cela pour un devoir.","Masquer les noms sur les copies de r\xE9f\xE9rence","Rendre les copies","Nommer chaque fichier d’apr\xE8s l’\xE9l\xE8ve et le devoir","Un PDF par \xE9l\xE8ve","83 %","83,3 %","83,33 %","Comment une moyenne de la classe ou une note de la p\xE9riode s’affiche dans l’onglet Notes et dans le carnet de notes. Rien n’est arrondi dans le calcul.","D\xE9cimales d’une moyenne","Masque les barres du navigateur. F fait de m\xEAme depuis n’importe o\xF9 sauf une zone de texte, et \xC9chap permet d’en sortir.","Plein \xE9cran","Plein \xE9cran","Quitter le plein \xE9cran","Votre propre liste : une comp\xE9tence, un standard, tout ce selon quoi vous voulez voir les notes.","Un nouvel objectif, avec vos mots","Ajouter","{name} retir\xE9.","Objectifs d’apprentissage","Objectif {n}","Facultatif. Un objectif est tout ce selon quoi vous voulez voir les notes : une comp\xE9tence comme \xAB Utilise des preuves \xBB, ou un standard de votre \xE9tablissement. Associez un objectif aux crit\xE8res de grille et aux questions de quiz, et chaque classe aura un onglet Objectifs.","Retirer","Ajouter un objectif d’apprentissage","D\xE9placer un objectif d’apprentissage","Renommer un objectif d’apprentissage","Retirer un objectif d’apprentissage","Associez les crit\xE8res de grille dans Configurer la grille et les questions de quiz dans Cases de quiz. Un objectif retir\xE9 dispara\xEEt de tout ce qui y \xE9tait associ\xE9 ; aucune note ne change.","Cet objectif est d\xE9j\xE0 dans la liste.","Monter","Ma configuration","Un dossier \xE0 part sur cet ordinateur o\xF9 {name} peut lire et modifier vos le\xE7ons, s\xE9quences, activit\xE9s, grilles et emploi du temps. Les brouillons enregistr\xE9s l\xE0 arrivent sur vos lignes de cours, marqu\xE9s comme non relus. Le travail de notation n’y va jamais.","Arriv\xE9 de votre dossier de Planification, non relu.","Ce navigateur a de nouveau besoin de votre autorisation pour","Revenir \xE0 votre version","Retour \xE0 votre version. Celle de {name} est sous Versions.","{a} nouveaux, {c} mis \xE0 jour depuis le dossier de Planification","{n} mis \xE0 jour depuis le dossier de Planification","{n} nouveaux depuis le dossier de Planification","Changer de dossier","Modifi\xE9 par {name} dans votre dossier de Planification, non relu. Votre version est sous Versions.","Ce dossier n’a pas pu \xEAtre utilis\xE9","Ce dossier contient des fichiers de notation de Grading Studio. Choisissez ou cr\xE9ez un dossier r\xE9serv\xE9 \xE0 la planification, comme \xAB Le\xE7ons \xBB.","Dossier de Planification","Lier le dossier de Planification","Dossier de Planification li\xE9 : {name}","Li\xE9 :","Regarder dans le dossier de Planification","Ce navigateur ne peut pas lier de dossier. Chrome ou Edge sur un ordinateur le peuvent.","Aucun dossier li\xE9.","Aucun changement dans le dossier de Planification","Autoriser \xE0 nouveau","Impossible de lire le dossier de Planification","Relisez-le, puis marquez-le comme relu.","Marquer comme relu","Ceci est l’exemple, donc lier un dossier est d\xE9sactiv\xE9 ici. Quittez l’exemple pour l’utiliser avec vos propres le\xE7ons.","Version de {name} (vous \xEAtes revenu \xE0 la v\xF4tre)","Code QR de Grading Studio","Pointez l’appareil photo de votre t\xE9l\xE9phone vers le code et touchez le lien, ou tapez l’adresse ci-dessus.","Sur iPhone : dans Safari, touchez Partager, puis Sur l’\xE9cran d’accueil.","Sur Android : dans Chrome, touchez le menu ⋮, puis Ajouter \xE0 l’\xE9cran d’accueil ou Installer l’application.","Ouvrez Grading Studio depuis l’\xE9cran d’accueil et touchez Se connecter avec Google. Utilisez le m\xEAme compte Google que sur cet ordinateur.","Vos classes, notes et t\xE2ches restent alors identiques sur les deux. Vous pouvez saisir des notes et consulter les copies sur le t\xE9l\xE9phone ; la correction se fait sur l’ordinateur.","Si Google indique qu’il n’a pas v\xE9rifi\xE9 l’application, touchez Param\xE8tres avanc\xE9s, puis Acc\xE9der \xE0 Grading Studio. La cl\xE9 de connexion a \xE9t\xE9 cr\xE9\xE9e pour votre copie sans \xEAtre examin\xE9e par Google, et l’application ne peut utiliser que son propre dossier cach\xE9 dans votre Drive.","Utiliser sur votre t\xE9l\xE9phone","Sur un t\xE9l\xE9phone, des boutons plus grands et des onglets en bas. Les copies restent sur l’ordinateur ; les notes, l’appel, les plans et les t\xE2ches fonctionnent ici.","Affichage t\xE9l\xE9phone","Prend effet la prochaine fois que la page s’ouvre sur un t\xE9l\xE9phone","Utiliser l’affichage t\xE9l\xE9phone sur un t\xE9l\xE9phone","Ouvrir la version t\xE9l\xE9phone","Pour le voir ici, ouvrez une fen\xEAtre \xE9troite de cette app. Elle contient le m\xEAme travail.","Par exemple IB MYP. Une nouvelle classe d’un enseignant MYP commence avec les crit\xE8res MYP. Laissez vide si cela ne s’applique pas.","Programme : {name}.","Programme","Le programme que vous enseignez","Aucun programme indiqu\xE9.","Changer votre programme","Votre travail ici attend pour se synchroniser.","Se reconnecter","Google vous demande de vous reconnecter","Connectez-vous avec le m\xEAme compte Google que sur votre ordinateur. Vos classes, notes, plans et t\xE2ches arrivent alors ici.","Se connecter avec Google","Retrouvez votre travail de l’ordinateur","Rien n’arrive \xE0 un assistant IA si vous ne lui donnez pas vous-m\xEAme un fichier. Les copies, les noms, les notes et les appr\xE9ciations restent dans ce navigateur et dans votre propre dossier li\xE9.","Partager avec votre assistant, dans la Configuration d’un devoir, cr\xE9e un fichier \xE0 lui donner : les copies avec les noms masqu\xE9s, ou seulement vos annotations. Chaque \xE9l\xE8ve devient un code au hasard, et la cl\xE9 des codes reste dans ce navigateur.","Le dossier de Planification ne contient que des le\xE7ons. Si vous laissez votre assistant travailler dans un dossier de votre ordinateur, choisissez celui-l\xE0 : le travail de notation n’y va jamais, et le Planificateur refuse un dossier qui contient des fichiers de notation.","Ma configuration, sous Classes, peut donner \xE0 votre assistant une consigne pour r\xE9diger votre configuration \xE0 votre place. Elle ne contient jamais rien sur un \xE9l\xE8ve.","Ce que votre assistant peut voir ou non","Confidentialit\xE9, dans l’Aide","Agrandit ou r\xE9duit les mots de l’app sur cet ordinateur. La copie que vous corrigez garde son propre zoom.","Taille du texte de l’app","Grande","Normale","Petite","Tr\xE8s grande","Votre fa\xE7on de travailler, en un seul bloc de texte : vos classes et leurs horaires, le calendrier, les p\xE9riodes, votre notation, les grilles et appr\xE9ciations enregistr\xE9es. Jamais rien sur un \xE9l\xE8ve. Importez-en un de votre assistant ou d’un coll\xE8gue, ou copiez le v\xF4tre pour un autre ordinateur.","Un sommaire est ajout\xE9 sur la diapositive 2","Votre assistant IA est {name}","Aucun assistant IA indiqu\xE9","Absents de la liste d’assistants de la barre lat\xE9rale : {list}","Tous les assistants que l’application conna\xEEt sont dans la liste de la barre lat\xE9rale","Votre assistant s’ouvre dans une fen\xEAtre \xE0 droite de l’\xE9cran","Votre assistant s’ouvre dans un nouvel onglet","Votre assistant s’ouvre sur {link}","Votre assistant s’ouvre sur sa page habituelle","Autres assistants avec un lien \xE0 vous : {list}","Aucun autre assistant n’a de lien \xE0 vous","Faire l’appel dans Grading Studio","Ne pas faire l’appel dans Grading Studio","{grade} \xE0 partir de {n} %","Notes : {list}",{one:"Importer {n} partie",other:"Importer {n} parties"},"Les notes ne d\xE9passent pas 100 %","V\xE9rifier",{one:"{n} appr\xE9ciation \xE0 choisir en corrigeant : \xAB {first} \xBB",other:"{n} appr\xE9ciations \xE0 choisir en corrigeant, comme \xAB {first} \xBB"},"Copier ma configuration","Copier la consigne","Cours pour {list}. Les classes du m\xEAme cours sont li\xE9es.","Les noms sont masqu\xE9s sur les copies de r\xE9f\xE9rence que vous exportez","Les noms ne sont pas masqu\xE9s sur les copies de r\xE9f\xE9rence que vous exportez",{one:"{n} partie de la configuration import\xE9e.",other:"{n} parties de la configuration import\xE9es."},"Quand un type est encore vide, les autres types sont utilis\xE9s","Un type encore vide compte pour 0","Rien \xE0 lire pour l’instant. Collez d’abord le texte de configuration.","C’est trop long pour une configuration. Une configuration fait quelques pages de texte au plus.","Aucune configuration trouv\xE9e dans ce texte. Une configuration commence par { et finit par }. Si votre assistant l’a coup\xE9e, redemandez-lui le bloc entier.",'Ce texte n’est pas une configuration Grading Studio : il n’a pas de ligne "gradingStudioSetup". Redemandez le bloc de configuration \xE0 votre assistant, avec la consigne.',{one:"{n} date au calendrier : {list}",other:"{n} dates au calendrier : {list}"},"Cela n’a pas march\xE9, et rien n’a \xE9t\xE9 chang\xE9. R\xE9essayez.","Une pause dure {n} minutes",{one:"Objectif du jour : {n} minute",other:"Objectif du jour : {n} minutes"},{one:"Objectif du jour : {n} copie",other:"Objectif du jour : {n} copies"},"Les heures libres sont propos\xE9es pour corriger","Les heures libres ne sont pas propos\xE9es pour corriger",{one:"Le temps cesse d’\xEAtre compt\xE9 apr\xE8s {n} minute sans activit\xE9",other:"Le temps cesse d’\xEAtre compt\xE9 apr\xE8s {n} minutes sans activit\xE9"},"Une s\xE9ance de concentration dure {n} minutes","Une s\xE9ance de le\xE7on dure {n} minutes","L’ambiance, le volume et le fond sonore de la musique","Musique lo-fi pendant une s\xE9ance","Pas de musique pendant une s\xE9ance","Pas d’objectif du jour","La pr\xE9paration hors des s\xE9ances de concentration compte apr\xE8s {n} minutes de travail continu","La pr\xE9paration ne compte que pendant les s\xE9ances de concentration","Les compteurs sont masqu\xE9s pendant une s\xE9ance de concentration","Les compteurs restent visibles pendant une s\xE9ance de concentration","Un objectif est propos\xE9 pour chaque s\xE9ance","Aucun objectif n’est propos\xE9 pour les s\xE9ances","Les copies les plus courtes d’abord pendant une s\xE9ance","Les copies dans leur ordre habituel pendant une s\xE9ance","Un l\xE9ger carillon \xE0 la fin d’une s\xE9ance ou d’une pause","Pas de carillon \xE0 la fin d’une s\xE9ance","Le temps restant s’affiche dans le nom de l’onglet du navigateur","Le temps restant ne s’affiche pas dans le nom de l’onglet du navigateur","Le temps de notation et de pr\xE9paration est compt\xE9","Le temps de notation et de pr\xE9paration n’est pas compt\xE9","Un bilan de la semaine le {day}",{one:"Objectif de la semaine : {n} minute",other:"Objectif de la semaine : {n} minutes"},"Pas de bilan de la semaine",{one:"Objectif de la semaine : {n} copie",other:"Objectif de la semaine : {n} copies"},"Les noms tap\xE9s sont trouv\xE9s et masqu\xE9s pour vous","Vous masquez les noms vous-m\xEAme","En plein \xE9cran, la liste des \xE9l\xE8ves et les outils se cachent jusqu’\xE0 ce que vous pointiez dessus","En plein \xE9cran, la liste des \xE9l\xE8ves se cache jusqu’\xE0 ce que vous pointiez dessus","En plein \xE9cran, la liste des \xE9l\xE8ves et les outils restent \xE0 c\xF4t\xE9 de la copie",{one:"{n} objectif : {list}",other:"{n} objectifs : {list}"},"Ma configuration","Pr\xE9sences","Ce qui compose une note","Semestre et jours de cong\xE9","Classes et emploi du temps","Commentaires enregistr\xE9s","Diapositives de le\xE7on","Minuteur de concentration et objectif du jour","Objectifs d’apprentissage","Votre notation","Correction et remise des copies","Largeur du panneau lat\xE9ral","Grilles enregistr\xE9es","Votre \xE9tablissement","Onglets de la classe","P\xE9riodes","\xC0 faire","Programme IB, crit\xE8res et seuils de note pour {list}","noir","bleu","vert","violet","rouge",{one:"{n} \xE9l\xE9ment concernant des \xE9l\xE8ves \xE9tait dans le texte. Il a \xE9t\xE9 laiss\xE9 de c\xF4t\xE9 : les \xE9l\xE8ves ne s’ajoutent que sur la page de leur classe.",other:"{n} \xE9l\xE9ments concernant des \xE9l\xE8ves \xE9taient dans le texte. Ils ont \xE9t\xE9 laiss\xE9s de c\xF4t\xE9 : les \xE9l\xE8ves ne s’ajoutent que sur la page de leur classe."},"Un lien vers le syst\xE8me de l’\xE9tablissement pour {list}","{list} et {n} de plus","La liste des \xE9l\xE8ves montre des pourcentages","La liste des \xE9l\xE8ves montre les points sur le total","Les boutons E-mail ouvrent l’app de messagerie de l’ordinateur","Les boutons E-mail ouvrent un nouveau message dans Gmail","Les boutons E-mail ouvrent un nouveau message dans Outlook sur le web",{one:"{n} nouvelle classe : {list}",other:"{n} nouvelles classes : {list}"},"Ajouter une diapositive ajoute une diapositive {name}","Aucun sommaire n’est ajout\xE9 sur la diapositive 2","Une note peut d\xE9passer 100 %","Une partie a \xE9t\xE9 \xE9crite pour une version plus r\xE9cente ou d’une fa\xE7on que celle-ci ne conna\xEEt pas, elle est donc laiss\xE9e telle quelle.",{one:"{n} jour de cong\xE9 : {list}",other:"{n} jours de cong\xE9 : {list}"},"La liste de saisie suit l’ordre des pr\xE9noms","La liste de saisie suit l’ordre des noms","La liste de saisie suit la liste de la classe","Le m\xEAme genre de texte, \xE0 partir de ce qui est ici, pour un autre ordinateur ou un coll\xE8gue. Il ne contient jamais de liste d’\xE9l\xE8ves, de note ni de copie.","Votre configuration","Le texte de configuration","Personnes sur la page \xC9tablissement : {list}","Ce qui changerait","Programme : {name}","Les points sont color\xE9s selon la r\xE9ussite : totale, partielle ou nulle","Les points sont \xE9crits en {ink}","Les points sont \xE9crits dans la couleur du stylo","Places pour des personnes sur la page \xC9tablissement : {list}","Crit\xE8res de grille : {list}","En cas de reprise, la moyenne des essais compte","En cas de reprise, la meilleure note compte","En cas de reprise, la derni\xE8re note compte",{one:"{name} ({n} crit\xE8re)",other:"{name} ({n} crit\xE8res)"},{one:"{n} nouvelle grille : {list}",other:"{n} nouvelles grilles : {list}"},"Nouvelles formulations pour {list}, que vous avez d\xE9j\xE0","Les jours d\xE9j\xE0 enregistr\xE9s sont conserv\xE9s.","Pour toutes vos classes. Les notes des devoirs ne changent pas ; les moyennes sont recalcul\xE9es \xE0 partir d’elles.","Ajout\xE9s au calendrier. Les jours de cong\xE9 d\xE9j\xE0 pr\xE9sents restent.","Les classes que vous avez d\xE9j\xE0 restent, avec leurs \xE9l\xE8ves et leur travail. Aucun \xE9l\xE8ve n’est ajout\xE9 ainsi.","Ajout\xE9es aux appr\xE9ciations que vous choisissez en corrigeant.","Pour chaque diaporama que vous cr\xE9erez d\xE9sormais.","Pour les associer aux crit\xE8res de grille et aux questions de quiz.","Les devoirs que vous avez d\xE9j\xE0 gardent leur grille et leur bar\xE8me, et aucune note ne change.","Aucune copie, annotation ni note ne change.","\xC0 choisir sur n’importe quel devoir, dans Configurer la grille.","Seulement les mots qu’utilise l’app. Rien n’y est connect\xE9.","Les autres pages restent sous Plus.","Un devoir compte pour la p\xE9riode o\xF9 tombe sa date de remise.","Supprim\xE9es : {list}. Leurs lignes vont dans la cat\xE9gorie qui correspond \xE0 leurs mots.","Rien ne changerait ici : tout est d\xE9j\xE0 comme chez vous.","Enregistrer comme fichier",{one:"Un bar\xE8me des points aux pourcentages ({n} palier)",other:"Un bar\xE8me des points aux pourcentages ({n} paliers)"},"Semestre du {from} au {to}","La feuille de notes montre aussi les notes trouv\xE9es sur les copies","La feuille de notes ne montre que les notes donn\xE9es dans l’app","Le texte des diapositives reste entre 28 et 36 pt","Le texte des diapositives peut avoir toute taille de 18 \xE0 44 pt","Copiez la consigne et donnez-la \xE0 votre assistant IA. Il vous demande ce qu’il ne sait pas encore et r\xE9dige votre configuration.","Copiez la consigne et donnez-la \xE0 {name}. Il vous demande ce qu’il ne sait pas encore et r\xE9dige votre configuration.","Collez ici ce qu’il vous renvoie, puis v\xE9rifiez. Rien ne change avant que vous ayez vu ce qui changerait.","Les \xE9l\xE8ves rendent leur travail sur {name}","Aucun syst\xE8me d’\xE9tablissement indiqu\xE9","formatif","en classe","sommatif","Pr\xE9sences","Graphiques","Objectifs","Carnet de notes","Travaux manquants","Une autre page","Appr\xE9ciations de bulletin","Plan de classe","\xC9l\xE8ves","Dans la rang\xE9e d’onglets : {list}","Seulement Devoirs, Carnet de notes et \xC9l\xE8ves dans la rang\xE9e d’onglets","Cat\xE9gories de t\xE2ches : {list}","Mots qui envoient une ligne vers {name} : {words}","{name}: {from} – {to}","{name} passe \xE0 : du {from} au {to}","Horaires de {list}, dans l’emploi du temps","Chaque crit\xE8re est not\xE9 de 0 \xE0 {n}","Chaque crit\xE8re est not\xE9 de 0 \xE0 {n}, en points entiers seulement","Not\xE9 avec un total sur {n}","Vos propres types : {list}","R\xE9tablir la configuration pr\xE9c\xE9dente","Tout est revenu comme avant l’import de la configuration.","R\xE9tabli, sauf ce que vous avez utilis\xE9 depuis.","Les plans de s\xE9quence sont rang\xE9s dans {name}","Aucun endroit indiqu\xE9 pour les plans de s\xE9quence","Nouvelles s\xE9quences dans {list}","Non compris, donc laiss\xE9 tel quel : {list}.","Un nouveau devoir commence avec {way}","IB 1 \xE0 7","des lettres","Crit\xE8res du PEI (IB MYP)","un pourcentage",null,"des crit\xE8res de grille","Un nouveau devoir commence avec {way} (actuellement {was})","Une note de la p\xE9riode se compose de {list}","Les points bonus s’ajoutent au travail en classe","Les points bonus s’ajoutent \xE0 la note de la p\xE9riode","Les fichiers que vous rendez sont nomm\xE9s d’apr\xE8s l’\xE9l\xE8ve et le devoir","Les fichiers que vous rendez gardent le nom qu’ils avaient \xE0 la remise","Chaque \xE9l\xE8ve re\xE7oit un seul PDF avec toutes ses copies","Chaque copie est rendue dans son propre fichier","Se reconnecter","La renouveler toute seule chaque heure","Google redemande toutes les heures. Activ\xE9, la petite fen\xEAtre de Google s’ouvre un instant, en g\xE9n\xE9ral quand vous revenez dans l’app. D\xE9sactiv\xE9, la synchronisation attend que vous appuyiez sur Se reconnecter.","La connexion a \xE9t\xE9 ferm\xE9e.","La connexion n’a pas abouti.","Connectez-vous avec Google et vos classes, notes, plans et t\xE2ches seront les m\xEAmes sur chaque ordinateur et t\xE9l\xE9phone o\xF9 vous vous connectez. Seul un dossier cach\xE9 propre \xE0 l’app dans votre Drive est utilis\xE9, et rien d’autre dans votre Drive n’est visible.",null,"Derni\xE8re synchronisation : {when}","La connexion Google fonctionne \xE0 l’adresse web de l’app, pas dans une copie ouverte depuis un fichier.","Impossible de joindre Google. V\xE9rifiez la connexion internet.","D\xE9connect\xE9 de Google","Google Drive n’est pas utilis\xE9 tant que l’exemple est ouvert.","Se connecter avec Google","Se d\xE9connecter","Google : {email}","Connect\xE9 en tant que {email}","attend que la page soit au premier plan","annotations synchronis\xE9es ; votre Google Drive est plein, les copies restent donc ici","non synchronis\xE9","annotations synchronis\xE9es ; copies pas encore envoy\xE9es","hors ligne : synchronisation d\xE8s votre retour en ligne","enregistrement…","envoi des copies…","reconnectez-vous pour synchroniser","synchronis\xE9","synchronisation…","Synchroniser","Seulement pour les mots \xE0 l’\xE9cran. Rien n’y est connect\xE9.","O\xF9 les \xE9l\xE8ves rendent leur travail","Son nom","Le syst\xE8me de mon \xE9tablissement","Sur papier, ou non pr\xE9cis\xE9","Ailleurs…","Changer l’endroit o\xF9 les \xE9l\xE8ves rendent leur travail","Pour un \xE9cran tactile. La souris et le pav\xE9 tactile fonctionnent comme toujours.","dessine, jusqu’\xE0 ce que vous utilisiez un stylet ; ensuite il d\xE9place la page","dessine toujours","Un doigt sur la copie","Tablette et stylet","d\xE9place toujours la page","Le trait du stylet s’\xE9largit quand vous appuyez plus fort","Deux doigts d\xE9placent toujours la page, et un pincement zoome. Tant que le stylet est sur la copie, une main pos\xE9e sur l’\xE9cran ne fait rien.","Laissez-le faire la configuration","Vous avez un assistant IA qui conna\xEEt votre fa\xE7on d’enseigner ?","Ajouter une autre classe","Une autre classe","Retour","Importer votre travail","Choisissez votre dossier Grading Studio, ou importez un fichier \xE0 emporter. Vos classes et votre travail viennent avec.","Vos r\xE9ponses n’ont pas pu \xEAtre enregistr\xE9es. R\xE9essayez.","Une classe, par exemple \xAB SVT 2de B \xBB","Continuer","Tout est pr\xEAt. Ouvrez ici des copies, ou ajoutez une classe dans la barre lat\xE9rale.","Tout est pr\xEAt. Ouvrez ici les copies d’une classe, ou cliquez sur une classe dans la barre lat\xE9rale pour ajouter ses \xE9l\xE8ves.","Choisir un dossier…","Enregistrement dans le dossier \xAB {name} \xBB en plus de ce navigateur.","Comment notez-vous d’habitude ?","Ce n’est que le point de d\xE9part d’un nouveau devoir. Tout devoir peut \xEAtre not\xE9 autrement.","Corrigez des copies, pr\xE9parez vos le\xE7ons, rendez le travail.","O\xF9 les \xE9l\xE8ves rendent-ils leurs travaux ?","Son nom","Le nom de la plateforme de votre \xE9tablissement","Vos classes, copies, annotations et notes sont gard\xE9es dans ce navigateur. Ce navigateur ne peut pas enregistrer seul dans un dossier (Chrome ou Edge sur un ordinateur le peuvent) : cr\xE9ez de temps en temps un fichier \xE0 emporter, dans R\xE9glages. La barre lat\xE9rale vous le rappelle.","O\xF9 garder votre travail ?","Vos classes, copies, annotations et notes sont gard\xE9es dans ce navigateur. Choisissez un dossier sur cet ordinateur et chaque enregistrement y ira aussi, avec une copie de chaque jour \xE0 laquelle revenir. Rien n’est envoy\xE9 en ligne.","Vous pouvez aussi le faire plus tard, dans les R\xE9glages.","Trois questions rapides et vous corrigez. Chaque r\xE9ponse pourra \xEAtre modifi\xE9e plus tard.","Les noms des \xE9l\xE8ves sont facultatifs et viennent plus tard : collez une liste sur la page de la classe, ou passez cette \xE9tape.","Vous utilisez d\xE9j\xE0 Grading Studio sur un autre ordinateur ?","Sur papier, ou je pr\xE9f\xE8re ne pas le dire","Vos classes","Votre notation","Emplacement du travail","D’abord d\xE9couvrir avec une classe d’exemple","Commencer","\xC9tape {n} sur 3","Seulement pour que l’application utilise son nom. Rien n’y est connect\xE9 et rien n’est envoy\xE9.","Qu’enseignez-vous ?"],null);export{o as default};
